package org.slavicmyths.cubeaudit;
import java.io.*;import java.nio.file.*;import java.lang.management.*;import jdk.jfr.*;
import net.minecraft.client.*;import net.minecraft.client.gui.screens.TitleScreen;import net.minecraft.core.*;import net.minecraft.core.registries.*;import net.minecraft.world.level.*;import net.minecraft.world.level.levelgen.*;import net.minecraft.world.level.levelgen.presets.*;import net.minecraft.world.Difficulty;import net.minecraft.world.entity.*;
import net.neoforged.api.distmarker.Dist;import net.neoforged.bus.api.SubscribeEvent;import net.neoforged.fml.common.EventBusSubscriber;import net.neoforged.neoforge.client.event.*;import net.neoforged.neoforge.event.tick.ServerTickEvent;import org.slavicmyths.guardians.*;
/** Staged client-only native renderers, not guardian encounter/AI acceptance. */
@EventBusSubscriber(modid="slavicmyths",value=Dist.CLIENT)
public final class CubeProbe {
 static final Path OUT=Path.of(System.getProperty("cube.output"));static PrintWriter events,frames,ticks;static Recording rec;static boolean opened,spawned,finished;static volatile int age;static long last,pre,interval,framePre,frameCpu;static final com.sun.management.ThreadMXBean CPU=(com.sun.management.ThreadMXBean)ManagementFactory.getThreadMXBean();static Entity[] actors;
 static void init()throws Exception{Files.createDirectories(OUT);events=new PrintWriter(Files.newBufferedWriter(OUT.resolve("events.txt")));frames=new PrintWriter(Files.newBufferedWriter(OUT.resolve("frames.csv")));ticks=new PrintWriter(Files.newBufferedWriter(OUT.resolve("ticks.csv")));frames.println("age,ms,render_ms,render_cpu_ms,focused,visible,iconified,paused,screen,width,height,camera_x,camera_y,camera_z,yaw,pitch,cap,epoch_ms");ticks.println("age,ms,interval_ns,heap,gc_count,gc_ms");rec=new Recording(Configuration.getConfiguration("profile"));rec.setMaxSize(256L*1024*1024);rec.start();}
 @SubscribeEvent public static void client(ClientTickEvent.Post e){var m=Minecraft.getInstance();if(!opened&&m.screen instanceof TitleScreen){opened=true;try{init();}catch(Exception ex){throw new RuntimeException(ex);}m.options.pauseOnLostFocus=false;m.options.renderDistance().set(8);m.options.simulationDistance().set(5);m.options.framerateLimit().set(144);m.options.enableVsync().set(false);m.options.tutorialStep=net.minecraft.client.tutorial.TutorialSteps.NONE;m.options.save();events.println("ACTIVE_OPTIONS window="+m.getWindow().getWidth()+"x"+m.getWindow().getHeight()+" rd8 sim5 vsyncfalse cap144 then uncapped GPU="+com.mojang.blaze3d.platform.GlUtil.getRenderer());events.flush();m.createWorldOpenFlows().createFreshLevel("CubeAudit-"+System.currentTimeMillis(),new LevelSettings("Cube audit",GameType.SURVIVAL,false,Difficulty.NORMAL,true,new GameRules(),WorldDataConfiguration.DEFAULT),new WorldOptions(330015,false,false),r->r.registryOrThrow(Registries.WORLD_PRESET).getHolderOrThrow(WorldPresets.FLAT).value().createWorldDimensions(),m.screen);return;}
  if(m.level==null||m.player==null||age<100)return;
  if(!spawned){spawned=true;VertexAudit.run(events);try{rec.stop();rec.dump(OUT.resolve("micro.jfr"));rec.close();rec=new Recording(Configuration.getConfiguration("profile"));rec.setMaxSize(256L*1024*1024);rec.start();}catch(Exception ex){throw new RuntimeException(ex);}stage(m);age=0;events.println("STAGED 1 Fire LOCKDOWN +1 Spring FLOOD +1 Spring WHIRL +1 Prison +1 Echo; client-only native render objects; no server AI claim");events.flush();}
  if(actors!=null){for(var a:actors){a.setDeltaMovement(net.minecraft.world.phys.Vec3.ZERO);a.tickCount=80;}for(var a:actors)if(a instanceof GuardianEntity g)set(g,"AGE",40);}
  if(age==4800){m.options.framerateLimit().set(260);events.println("CAP_CHANGE 260 age="+age);events.flush();}
  if(age==2400||age==4800||age==6600){try(var im=Screenshot.takeScreenshot(m.getMainRenderTarget())){im.writeToFile(OUT.resolve("scene-"+age+".png"));}catch(Exception ex){throw new RuntimeException(ex);}}
  if(age>=6600&&!finished){finished=true;events.println("COMPLETE warm120s cap144sample120s uncappedwarm30s uncappedsample60s");events.flush();frames.flush();ticks.flush();try{rec.stop();rec.dump(OUT.resolve("profile.jfr"));rec.close();}catch(Exception ex){throw new RuntimeException(ex);}m.stop();}
 }
 @SuppressWarnings("unchecked")static <T>void set(GuardianEntity g,String name,T value){try{var f=GuardianEntity.class.getDeclaredField(name);f.setAccessible(true);g.getEntityData().set((net.minecraft.network.syncher.EntityDataAccessor<T>)f.get(null),value);}catch(Exception ex){throw new RuntimeException(ex);}}
 static void stage(Minecraft m){actors=new Entity[]{GuardianContent.FIRE.get().create(m.level),GuardianContent.WATER.get().create(m.level),GuardianContent.WATER.get().create(m.level),GuardianContent.PRISON.get().create(m.level),GuardianContent.ECHO.get().create(m.level)};for(int i=0;i<actors.length;i++){var a=actors[i];a.setId(-3300-i);a.moveTo(-8+i*4,-60,8,180,0);a.setNoGravity(true);if(a instanceof Mob mob)mob.setNoAi(true);if(a instanceof GuardianEntity g){set(g,"STATE",i==0?GuardianRules.LOCKDOWN:i==1?GuardianRules.FLOOD:GuardianRules.WHIRL);set(g,"AGE",40);set(g,"MIN",new BlockPos(-12,-60,2));set(g,"MAX",new BlockPos(12,-55,18));set(g,"ORIGIN",i==1?new BlockPos(-78,-61,-8):new BlockPos(0,-60,8));}m.level.addEntity(a);}m.player.setYRot(0);m.player.setXRot(12);}
 @SubscribeEvent public static void before(ServerTickEvent.Pre e){pre=System.nanoTime();}
 @SubscribeEvent public static void after(ServerTickEvent.Post e){if(events==null||finished)return;long n=System.nanoTime();var s=e.getServer();if(s.getPlayerList().getPlayers().isEmpty())return;var p=s.getPlayerList().getPlayers().getFirst();var w=p.serverLevel();if(age==0&&!spawned){w.getGameRules().getRule(GameRules.RULE_DOMOBSPAWNING).set(false,s);w.getGameRules().getRule(GameRules.RULE_DAYLIGHT).set(false,s);w.setDayTime(6000);p.teleportTo(w,0,-60,-14,0,12);p.setInvulnerable(true);}age++;if(spawned&&age>300){var rt=Runtime.getRuntime();long gc=0,gcms=0;for(var b:ManagementFactory.getGarbageCollectorMXBeans()){gc+=b.getCollectionCount();gcms+=b.getCollectionTime();}ticks.println(age+","+(n-pre)/1e6+","+(interval==0?0:n-interval)+","+(rt.totalMemory()-rt.freeMemory())+","+gc+","+gcms);}interval=n;}
 @SubscribeEvent public static void frameBefore(RenderFrameEvent.Pre e){framePre=System.nanoTime();frameCpu=CPU.getCurrentThreadCpuTime();}
 @SubscribeEvent public static void frame(RenderFrameEvent.Post e){long n=System.nanoTime(),cpu=CPU.getCurrentThreadCpuTime();var m=Minecraft.getInstance();if(spawned&&age>300&&!finished){long win=m.getWindow().getWindow();var c=m.gameRenderer.getMainCamera();var p=c.getPosition();frames.println(age+","+(last==0?0:(n-last)/1e6)+","+(n-framePre)/1e6+","+(cpu-frameCpu)/1e6+","+m.isWindowActive()+","+org.lwjgl.glfw.GLFW.glfwGetWindowAttrib(win,org.lwjgl.glfw.GLFW.GLFW_VISIBLE)+","+org.lwjgl.glfw.GLFW.glfwGetWindowAttrib(win,org.lwjgl.glfw.GLFW.GLFW_ICONIFIED)+","+m.isPaused()+","+(m.screen==null?"none":m.screen.getClass().getSimpleName())+","+m.getWindow().getWidth()+","+m.getWindow().getHeight()+","+p.x+","+p.y+","+p.z+","+c.getYRot()+","+c.getXRot()+","+m.options.framerateLimit().get()+","+System.currentTimeMillis());if(age%100==0)frames.flush();}last=n;}
}
